        forall |a: A| domain.contains(a) ==> eventually(always(a_to_p(a))).satisfied_by(ex.suffix(i)),
    ensures
        exists |j: nat| forall |a: A| domain.contains(a) ==> always(a_to_p(a)).satisfied_by(ex.suffix(i + j)),
    decreases domain.len(),
{
    if domain.len() == 0 {
        // Empty domain: witness j = 0 works trivially
        assert(forall |a: A| domain.contains(a) ==> always(a_to_p(a)).satisfied_by(ex.suffix(i + 0)));
    } else {
        let a0 = domain.choose();
        // domain.contains(a0) from lemma_set_choose_len (broadcast)

        // Inductive hypothesis on domain.remove(a0)
        assert forall |a: A| domain.remove(a0).contains(a) implies
            eventually(always(a_to_p(a))).satisfied_by(ex.suffix(i))
        by {
            // domain.remove(a0).contains(a) implies domain.contains(a)
            // (by lemma_set_remove_different, broadcast)
            assert(domain.contains(a));
        };
        exists_uniform_always_witness(ex, i, a_to_p, domain.remove(a0));
        let j_rest: nat = choose |j: nat| forall |a: A|
            domain.remove(a0).contains(a) ==> always(a_to_p(a)).satisfied_by(ex.suffix(i + j));

        // Get witness j0 for a0
        assert(eventually(always(a_to_p(a0))).satisfied_by(ex.suffix(i)));
        // Unfold eventually: exists k, always(a_to_p(a0)).sat(ex.suffix(i).suffix(k))
        assert(exists |k: nat| always(a_to_p(a0)).satisfied_by(ex.suffix(i).suffix(k)));
        let j0: nat = choose |k: nat| always(a_to_p(a0)).satisfied_by(ex.suffix(i).suffix(k));
        // By choose axiom:
        assert(always(a_to_p(a0)).satisfied_by(ex.suffix(i).suffix(j0)));
        // Convert using suffix_suffix_eq:
        suffix_suffix_eq(ex, i, j0);
        assert(always(a_to_p(a0)).satisfied_by(ex.suffix(i + j0)));

        // Take max of j0 and j_rest
        let j_max: nat = if j0 >= j_rest { j0 } else { j_rest };

        // Show j_max works for all elements of domain
        assert forall |a: A| domain.contains(a) implies
            always(a_to_p(a)).satisfied_by(ex.suffix(i + j_max))
        by {
            if a == a0 {
                // already have: always(a_to_p(a0)).sat(ex.suffix(i + j0))
                // j0 <= j_max, so propagate forward
                assert(j0 <= j_max);
                always_propagate_to(ex, a_to_p(a0), i + j0, i + j_max);
            } else {
                // a is in domain.remove(a0) (since a != a0 and domain.contains(a))
                assert(domain.remove(a0).contains(a));
                // from j_rest: always(a_to_p(a)).sat(ex.suffix(i + j_rest))
                assert(always(a_to_p(a)).satisfied_by(ex.suffix(i + j_rest)));
                // j_rest <= j_max, so propagate forward
                assert(j_rest <= j_max);
                always_propagate_to(ex, a_to_p(a), i + j_rest, i + j_max);
            }
        };
        // j_max is our witness
    }
}

pub proof fn leads_to_always_tla_forall<T, A>(spec: TempPred<T>, p: TempPred<T>, a_to_p: spec_fn(A)->TempPred<T>, domain: Set<A>)
    requires
        forall |a: A| spec.entails(p.leads_to(always(#[trigger] a_to_p(a)))),
        domain.finite(),
        domain.len() > 0,
        forall |a: A| #[trigger] domain.contains(a),
    ensures spec.entails(p.leads_to(always(tla_forall(a_to_p)))),
{
    // Unfold entails: for all ex satisfying spec, show p.leads_to(always(tla_forall(a_to_p))).satisfied_by(ex)
    assert forall |ex: Execution<T>| spec.satisfied_by(ex) implies
        p.leads_to(always(tla_forall(a_to_p))).satisfied_by(ex)
    by {
        // p.leads_to(q) = always(p.implies(eventually(q)))
        // We need: forall i, p.implies(eventually(always(tla_forall(a_to_p)))).satisfied_by(ex.suffix(i))
        assert forall |i: nat| #[trigger]
            p.implies(eventually(always(tla_forall(a_to_p)))).satisfied_by(ex.suffix(i))
        by {
            if p.satisfied_by(ex.suffix(i)) {
                // For each a: A, derive eventually(always(a_to_p(a))).satisfied_by(ex.suffix(i))
                assert forall |a: A| eventually(always(a_to_p(a))).satisfied_by(ex.suffix(i)) by {
                    // Trigger the precondition for this specific a
                    assert(spec.entails(p.leads_to(always(a_to_p(a)))));
                    // spec.entails(...) => for all ex', spec.sat(ex') => leads_to.sat(ex')
                    // With ex' = ex and spec.sat(ex):
                    assert(p.leads_to(always(a_to_p(a))).satisfied_by(ex));
                    // p.leads_to(q) = always(p.implies(eventually(q)))
                    // always(...).sat(ex) => forall i', p.implies(eventually(q)).sat(ex.suffix(i'))
                    // With i' = i:
                    assert(p.implies(eventually(always(a_to_p(a)))).satisfied_by(ex.suffix(i)));
                    // p.implies(q).sat(ex) and p.sat(ex) => q.sat(ex)
                    implies_apply(ex.suffix(i), p, eventually(always(a_to_p(a))));
                };

                // Build precondition for exists_uniform_always_witness
                assert forall |a: A| domain.contains(a) ==>
                    eventually(always(a_to_p(a))).satisfied_by(ex.suffix(i))
                by {
                    // domain.contains(a) is given; use the above forall
                };

                // Find uniform witness j: forall a in domain, always(a_to_p(a)).sat(ex.suffix(i+j))
                exists_uniform_always_witness(ex, i, a_to_p, domain);
                let j: nat = choose |j: nat| forall |a: A|
                    domain.contains(a) ==> always(a_to_p(a)).satisfied_by(ex.suffix(i + j));

                // Show always(tla_forall(a_to_p)).satisfied_by(ex.suffix(i + j))
                assert(always(tla_forall(a_to_p)).satisfied_by(ex.suffix(i + j))) by {
                    assert forall |k: nat| #[trigger]
                        tla_forall(a_to_p).satisfied_by(ex.suffix(i + j).suffix(k))
                    by {
                        // tla_forall(a_to_p).sat(ex') = forall a, a_to_p(a).sat(ex')
                        assert forall |a: A| #[trigger]
                            a_to_p(a).satisfied_by(ex.suffix(i + j).suffix(k))
                        by {
                            // domain.contains(a) for all a
                            assert(domain.contains(a));
                            // always(a_to_p(a)).sat(ex.suffix(i+j))
                            // = forall k', a_to_p(a).sat(ex.suffix(i+j).suffix(k'))
                            // with k' = k:
                            assert(always(a_to_p(a)).satisfied_by(ex.suffix(i + j)));
                        };
                    };
                };

                // Convert: ex.suffix(i+j) == ex.suffix(i).suffix(j)
                suffix_suffix_eq(ex, i, j);
                // So always(tla_forall(a_to_p)).satisfied_by(ex.suffix(i).suffix(j))
                // Use witness j for eventually
                eventually_proved_by_witness(ex.suffix(i), always(tla_forall(a_to_p)), j);
                // Result: eventually(always(tla_forall(a_to_p))).satisfied_by(ex.suffix(i))
            }
        };
    };
}


}

